def H(t,sz=14,al=WD_ALIGN_PARAGRAPH.LEFT):
    p=doc.add_paragraph(); p.alignment=al; r=p.add_run(t); r.bold=True; r.font.size=Pt(sz); r.font.name='Times New Roman'
