    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY; p.paragraph_format.space_after=Pt(6); r=p.add_run(t); r.font.size=Pt(12); r.font.name='Times New Roman'
